import{at as e,it as t,n,vt as r}from"./chunks/framework.BPeR9Rpo.js";var i=JSON.parse(`{"title":"Änderungshistorie","description":"","frontmatter":{"title":"Änderungshistorie","covers":{"screens":["SCR-026","SCR-027"],"stories":["US-098","US-099","US-100","US-101","US-102","US-103"]}},"headers":[],"relativePath":"de/usage/change-history.md","filePath":"de/usage/change-history.md"}`),a={name:`de/usage/change-history.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="anderungshistorie" tabindex="-1">Änderungshistorie <a class="header-anchor" href="#anderungshistorie" aria-label="Permalink to “Änderungshistorie”">​</a></h1><p>Jede Änderung an einer Entität erzeugt eine neue Version. Die Seite <em>Änderungshistorie</em> zeigt, wer eine Entität wann geändert hat, welche Felder jede Version geändert hat, und die Werte davor und danach. Du brauchst die Berechtigung <code>entity:read</code>; die Rollen <code>viewer</code>, <code>analyst</code> und <code>enterprise-architect</code> haben sie.</p><h2 id="die-anderungshistorie-offnen" tabindex="-1">Die Änderungshistorie öffnen <a class="header-anchor" href="#die-anderungshistorie-offnen" aria-label="Permalink to “Die Änderungshistorie öffnen”">​</a></h2><p>Wähle in einem <a href="./catalogs">Katalog</a> oder in einem Katalog des <a href="./portal">Portals</a> in der Zeile einer Entität <em>Historie</em>. Die Seite öffnet sich mit den Versionen der Entität, die neueste zuerst. <em>Zurück zum Katalog</em> führt zum Katalog, von dem du gekommen bist, auf derselben Seite und mit derselben Sortierung.</p><h2 id="die-eintrage-lesen" tabindex="-1">Die Einträge lesen <a class="header-anchor" href="#die-eintrage-lesen" aria-label="Permalink to “Die Einträge lesen”">​</a></h2><p>Jeder Eintrag zeigt:</p><ul><li>die <strong>Versionsnummer</strong>, bei der ersten Version <em>Erstellt</em>;</li><li>die <strong>Zeit</strong> der Änderung in deiner lokalen Zeitzone;</li><li>die <strong>Person</strong>, die die Änderung gemacht hat;</li><li>die <strong>geänderten Felder</strong>: Systemfelder wie <em>Name</em> oder <em>Beschreibung</em> und die Eigenschaften mit ihrer Beschriftung.</li></ul><p>Die Einträge nennen die geänderten Felder. Ihre Werte erscheinen, wenn du eine Version öffnest.</p><p>Eine Entität, die nach ihrer Erstellung nie geändert wurde, zeigt <em>Keine Änderungen seit der Erstellung. Erstellt am {Datum} von {Person}.</em></p><h2 id="die-werte-einer-version-ansehen" tabindex="-1">Die Werte einer Version ansehen <a class="header-anchor" href="#die-werte-einer-version-ansehen" aria-label="Permalink to “Die Werte einer Version ansehen”">​</a></h2><p>Wähle in einem Eintrag <em>Änderungen anzeigen</em>. Er listet jedes geänderte Feld mit seinem alten Wert rot und durchgestrichen und seinem neuen Wert grün; ein Feld ohne Wert zeigt <em>—</em>. Nur Felder, deren Wert sich unterscheidet, erscheinen. <em>Erstellt</em> hat keine Änderungen zum Anzeigen.</p><p><em>Vollständigen Stand vN anzeigen</em> listet jedes Feld der Entität so, wie es in dieser Version war: die Systemfelder und die Eigenschaften ihres Entitätstyps, auch leere. Es sind die Eigenschaften, die dem Entitätstyp zum Zeitpunkt der Version zugeordnet waren. Hat ein Paketimport eine Zuordnung später entfernt, fehlt eine leere Eigenschaft dieser Zuordnung in älteren Ständen; eine Eigenschaft, die damals einen Wert hatte, erscheint immer.</p><p>Versionen lassen sich weder ändern noch löschen.</p><h2 id="zwei-versionen-vergleichen" tabindex="-1">Zwei Versionen vergleichen <a class="header-anchor" href="#zwei-versionen-vergleichen" aria-label="Permalink to “Zwei Versionen vergleichen”">​</a></h2><p>Wähle <em>Vergleichen</em> und dann zwei Versionen. Ein Bereich über der Zeitleiste zeigt die Felder, deren Wert sich zwischen der früheren und der späteren Version unterscheidet. Ein Feld, das geändert und später zurückgeändert wurde, erscheint nicht. Wählst du eine dritte Version, ersetzt sie die zuerst gewählte. <em>Vergleich beenden</em> schliesst den Bereich.</p><h2 id="eine-fruhere-version-wiederherstellen" tabindex="-1">Eine frühere Version wiederherstellen <a class="header-anchor" href="#eine-fruhere-version-wiederherstellen" aria-label="Permalink to “Eine frühere Version wiederherstellen”">​</a></h2><p>Mit den Berechtigungen <code>entity:write</code> und <code>entity:restore</code> bietet jeder Eintrag ausser der aktuellen Version <em>Diese Version wiederherstellen</em>; die Rolle <code>enterprise-architect</code> hat beide. Die Aktion öffnet einen Dialog, der zeigt, was die Wiederherstellung tun würde, bevor sich etwas ändert:</p><ul><li>jedes Feld, dessen aktueller Wert von der Version abweicht, mit dem aktuellen Wert durchgestrichen und dem Wert nach der Wiederherstellung;</li><li>die Felder, die <strong>nicht wiederhergestellt</strong> werden, mit dem Grund: <ul><li><em>fehlende Berechtigung</em>: Du darfst die Eigenschaft nach der <a href="./../administration/property-visibility">Sichtbarkeit von Eigenschaften</a> nicht schreiben;</li><li><em>Die Eigenschaft gehört nicht mehr zum Entitätstyp</em>: Ihre Zuordnung zum Entitätstyp wurde inzwischen entfernt;</li><li><em>Der Wert ist nicht mehr gültig</em>: Die Eigenschaft akzeptiert den Wert nicht mehr, zum Beispiel einen entfernten Listenwert;</li></ul></li><li>Warnungen für Pflicht- oder empfohlene Eigenschaften, die danach leer wären. Sie blockieren die Wiederherstellung nie; eine leere Pflichteigenschaft wird danach als fehlend markiert, wie nach einer Änderung des Entitätstyps.</li></ul><p>Wiederhergestellt werden der Name, die Beschreibung, das Kennzeichen <em>logisch</em> und die Eigenschaften. Die ID, der Entitätstyp sowie Quelle und Ziel einer Verbindung ändern sich nie. Du kannst einen Grund mit bis zu 1000 Zeichen angeben. <em>Wiederherstellen</em> ist deaktiviert, wenn nichts wiederhergestellt werden kann; <em>Abbrechen</em> ändert nichts.</p><p>Die Wiederherstellung schreibt eine neue Version. Sie trägt das Kennzeichen <em>Wiederhergestellt aus vN</em> und den Grund. Die Version vor der Wiederherstellung bleibt unverändert in der Historie, sodass du auch zu diesem Stand zurückkehren kannst.</p><p>Hat jemand die Entität geändert, nachdem du den Dialog geöffnet hast, sagt der Dialog das und zeigt die Vorschau des aktuellen Stands. Prüfe sie und bestätige erneut.</p><h2 id="eingeschrankte-felder" tabindex="-1">Eingeschränkte Felder <a class="header-anchor" href="#eingeschrankte-felder" aria-label="Permalink to “Eingeschränkte Felder”">​</a></h2><p>Eine Eigenschaft, die du nach der <a href="./../administration/property-visibility">Sichtbarkeit von Eigenschaften</a> nicht lesen darfst, zeigt nie ihren Wert, weder in den Änderungen noch im vollständigen Stand. Je nach den Einstellungen deiner Rollen für den Entitätstyp erscheint das Feld mit dem Badge <em>Eingeschränkt</em>, oder es fehlt. Fehlen alle Felder einer Version, bleibt die Version ohne Felder in der Liste, damit die Nummerierung keine Lücken hat.</p><h2 id="filtern-und-mehr-laden" tabindex="-1">Filtern und mehr laden <a class="header-anchor" href="#filtern-und-mehr-laden" aria-label="Permalink to “Filtern und mehr laden”">​</a></h2><ul><li><strong>Person:</strong> Wähle eine Person, um nur ihre Versionen zu sehen. Die Liste bietet alle an, die die Entität geändert haben.</li><li><strong>Zeitraum:</strong> Wähle ein Start- und ein Enddatum. Beide Tage zählen ganz: Eine Version am Start- oder am Enddatum wird angezeigt.</li></ul><p>Die Seite zeigt zuerst 50 Versionen. <em>Mehr laden</em> fügt die nächsten 50 hinzu.</p><h2 id="uber-die-api" tabindex="-1">Über die API <a class="header-anchor" href="#uber-die-api" aria-label="Permalink to “Über die API”">​</a></h2><p><code>GET /entities/{id}/history</code> liefert die Versionen, die neueste zuerst, mit <code>from</code> und <code>to</code> (Zeitpunkte, einschliesslich), <code>actorId</code>, <code>page</code>, <code>pageSize</code> (1 bis 200, Standard 50) und <code>cursor</code> (der <code>nextCursor</code> der vorigen Seite, gesendet mit <code>page</code> + 1). Die Antwort nennt die Erstellung in <code>created</code> und alle Personen, die eine Version gemacht haben, in <code>actors</code>, unabhängig von den Filtern. Ein Start nach dem Ende wird mit 400 und <code>from</code> beantwortet, eine unbekannte Entität mit 404.</p><p><code>GET /entities/{id}/versions/{version}</code> liefert den vollständigen Stand einer Version in <code>fields</code>, jedes mit <code>field</code>, <code>label</code>, <code>dataType</code>, <code>value</code> und <code>restricted</code>. <code>GET /entities/{id}/diff?from=2&amp;to=7</code> liefert die Felder, deren Wert sich zwischen zwei Versionen unterscheidet, in <code>changes</code>, jedes mit <code>oldValue</code>, <code>newValue</code> und <code>redacted</code>; die Änderungen der Version N sind <code>from=N-1&amp;to=N</code>. <code>from</code> muss mindestens 1 sein und vor <code>to</code> liegen, sonst 400 mit <code>from</code>; eine unbekannte Version wird mit 404 beantwortet. <code>PUT</code> und <code>DELETE</code> auf eine Version werden mit 405 beantwortet.</p><p><code>GET /entities/{id}/restore?targetVersion=3</code> liefert die Vorschau einer Wiederherstellung: <code>currentVersion</code> und in <code>fields</code> jedes abweichende Feld mit <code>currentValue</code>, <code>targetValue</code>, <code>redacted</code>, <code>restore</code> und <code>reason</code> (<code>write-protected</code>, <code>not-mapped</code>, <code>invalid-value</code>), dazu die <code>warnings</code>. <code>POST /entities/{id}/restore</code> mit <code>{&quot;targetVersion&quot;: 3, &quot;reason&quot;: &quot;…&quot;}</code> stellt die Entität wieder her und braucht den Header <code>If-Match: &quot;5&quot;</code> mit der aktuellen Version: Ohne ihn lautet die Antwort 428, mit einer anderen Version 412 <code>stale-version</code> mit <code>currentVersion</code>. Die Zielversion muss mindestens 1 sein und vor der aktuellen Version liegen (400 mit <code>targetVersion</code>); eine spätere Version wird mit 404 beantwortet. Eine Wiederherstellung ohne etwas wiederherzustellen wird mit 422 <code>nothing-to-restore</code> beantwortet. Die Historie nennt die aktuelle Version in <code>currentVersion</code> und kennzeichnet eine wiederhergestellte Version mit <code>restoredFromVersion</code> und <code>reason</code>.</p>`,30)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};